with doc (d) as (values ($seed${"server_name":{"be4b140c-f5a3-487c-b301-8b66b17086fa":{"tr":"Descall Topluluk","en":"Descall Community","de":"Descall Community","es":"Comunidad Descall","fr":"Communauté Descall","pt-BR":"Comunidade Descall","ru":"Сообщество Descall"}},"server_description":{"be4b140c-f5a3-487c-b301-8b66b17086fa":{"tr":"Descall'un resmi topluluk sunucusu. Yeni gelenler burada tanışır, soru sorar, oyun ve sohbet arkadaşı bulur. Duyurular, ipuçları ve etkinlikler de burada.","en":"The official Descall community server. Newcomers meet people here, ask questions and find friends to play and chat with. Announcements, tips and events live here too.","de":"Der offizielle Community-Server von Descall. Hier lernen sich Neue kennen, stellen Fragen und finden Leute zum Zocken und Quatschen. Ankündigungen, Tipps und Events gibt es auch hier.","es":"El servidor oficial de la comunidad de Descall. Aquí los recién llegados conocen gente, hacen preguntas y encuentran con quién jugar y charlar. También hay anuncios, consejos y eventos.","fr":"Le serveur communautaire officiel de Descall. Les nouveaux venus s'y rencontrent, posent leurs questions et trouvent des amis pour jouer et discuter. Annonces, astuces et événements sont aussi ici.","pt-BR":"O servidor oficial da comunidade Descall. Aqui quem está chegando conhece gente nova, tira dúvidas e encontra amigos para jogar e conversar. Anúncios, dicas e eventos também ficam aqui.","ru":"Официальный сервер сообщества Descall. Здесь новички знакомятся, задают вопросы и находят друзей для игр и общения. Анонсы, советы и мероприятия тоже здесь."}},"channel_name":{"3bda105d-e9e7-42a5-8959-76b9749728d2":{"tr":"Başla","en":"Start Here","de":"Los geht's","es":"Empieza aquí","fr":"Pour commencer","pt-BR":"Comece aqui","ru":"Начало"},"2accd626-957e-4061-b124-c04cae1ceda3":{"tr":"Sohbet","en":"Chat","de":"Chat","es":"Charla","fr":"Discussion","pt-BR":"Papo","ru":"Общение"},"4cecb85e-8516-419c-a0b7-78589c5238eb":{"tr":"Destek","en